#!/bin/sh
# First start of the bundle's database: the application role (no
# BYPASSRLS: row-level security backs every tenant predicate). Its password
# is generated by the gateway (hex, so it needs no quoting).
set -eu
psql -v ON_ERROR_STOP=1 --username postgres --dbname deployer <<SQL
CREATE ROLE deployer_app LOGIN PASSWORD '${DEPLOYER_APP_PASSWORD}' NOBYPASSRLS;
GRANT CONNECT ON DATABASE deployer TO deployer_app;
SQL
